                if Na & ~union & ((1 << n) - 1) >> (b + 1):
                    return False
            # update D and U for the next b: add d < a adjacent to vb
            for d in range(a):
                if masks[order[d]] >> vb & 1:
                    empty = False
                    union |= masks[order[d]]
